from fractions import Fraction

def T(r):
    """Mobius transformation T(r) = (r-1)/r"""
    if r == 0:
        # Should not happen with our inputs, but good practice
        return None 
    return (r - 1) / r

def iterate_T(r_start):
    sequence = [r_start]
    history = {r_start}
    current = r_start
    k = 0

    while True:
        current = T(current)
        k += 1

        if current is None:
            break

        # Check for cycle/repeat
        if current in history:
            # Found a cycle
            return sequence, k, f"Cycle of length {k - len(list(history))}"

        # Check for 'known point' (we don't have specific known points yet, 
        # so we rely on cycles or arbitrarily stopping if it gets too complicated/large)

        sequence.append(current)
        history.add(current)

        # Safety break for very long sequences if no cycle is found quickly
        if k > 10:
            return sequence, k, "Length > 10 (Needs independent evaluation)"

# Arguments A = {7/3, 11/4, 2024/5, 109/11, 3/71, 5/204}
args = [
    Fraction(7, 3), 
    Fraction(11, 4), 
    Fraction(2024, 5), 
    Fraction(109, 11), 
    Fraction(3, 71), 
    Fraction(5, 204)
]

results = {}
for i, r_start in enumerate(args):
    seq, k, status = iterate_T(r_start)
    results[i] = {
        "start": r_start,
        "sequence": seq,
        "length": k,
        "status": status
    }

for i, res in results.items():
    print(f"--- Argument {i+1} (Start: {res['start']}) ---")
    print(f"Sequence (up to iteration {res['length']}): {[str(r) for r in res['sequence']]}")
    print(f"Status: {res['status']}")
